const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');
const arrows=['↑','↓','←','→'],keymap={ArrowUp:'↑',ArrowDown:'↓',ArrowLeft:'←',ArrowRight:'→',w:'↑',s:'↓',a:'←',d:'→'};
let state='intro',level=1,score=0,coins=0,delivered=0,quota=6,time=60,address=12,needed=2,boxes=[],selected=-1,step=0,parcelTime=0,parcelMax=1,streak=0,up={clock:0,sort:0,tip:0},paused=false,sound=false,audio,offset=0,targetOffset=0,flight=null,particles=[],last=performance.now(),worldTime=0,toastUntil=0;
let best=0;try{best=+localStorage.getItem('parcelBest')||0}catch(e){}$('best').textContent='BEST '+best;
function beep(freq=420){if(!sound)return;audio??=new(window.AudioContext||window.webkitAudioContext)();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.045,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);o.start();o.stop(audio.currentTime+.16)}
function toast(s){$('toast').textContent=s;$('toast').classList.add('show');toastUntil=performance.now()+1800}
function modal(html){$('modal').innerHTML=html;$('overlay').hidden=false}function hide(){$('overlay').hidden=true}
function intro(){modal('<span class="eyebrow">WELCOME TO THE NEIGHBORHOOD</span><h1>Little parcels.<br>Big delivery energy.</h1><p>A cozy little delivery game. Find the right boxes, follow their arrows, and keep Maple Lane smiling.</p><div class="step"><b>01</b> Match the house number in your cargo tray.</div><div class="step"><b>02</b> Select with 1–4, then type the arrow sequence.</div><div class="step"><b>03</b> Meet your quota. Keep going for bonus tips.</div><button class="primary" id="start">Let’s hit the road →</button>');$('start').onclick=()=>{hide();startRound()}}
function startRound(){state='playing';paused=false;delivered=0;quota=6+(level-1)*2;time=Math.max(32,62-(level-1)*4)+up.clock*8;needed=1+Math.floor(Math.random()*3);selected=-1;step=0;streak=0;makeBoxes();update()}
function makeBoxes(){boxes=Array.from({length:4},()=>{let size=Math.floor(Math.random()*3);return{address:address+2+2*Math.floor(Math.random()*5),size,seq:Array.from({length:3+size+(level>3?1:0)},()=>arrows[Math.floor(Math.random()*4)])}});let i=Math.floor(Math.random()*4);boxes[i].address=address;if(Math.random()<.35)boxes[(i+2)%4].address=address;selected=-1;step=0;renderBoxes()}
function renderBoxes(){ $('boxes').innerHTML=boxes.map((b,i)=>'<button class="box '+(selected===i?'selected':'')+'" data-i="'+i+'" aria-label="Box '+(i+1)+', house '+b.address+', '+['small','medium','large'][b.size]+'"><span class="slot">'+(i+1)+'</span><span class="parcel-icon" style="scale:'+(.8+b.size*.12)+'"></span><strong>No. '+b.address+'</strong><small>'+['SMALL PARCEL','MEDIUM PARCEL','LARGE PARCEL'][b.size]+'</small><div class="keys">'+b.seq.map((k,j)=>'<span class="key '+(selected===i?(j<step?'done':j===step?'next':''):'')+'">'+k+'</span>').join('')+'</div><div class="bar"><i style="width:'+(selected===i?parcelTime/parcelMax*100:100)+'%"></i></div></button>').join('');document.querySelectorAll('.box').forEach(b=>b.onclick=()=>choose(+b.dataset.i));$('instruction').textContent=selected<0?'Find the parcel for house '+address:'Type the arrows to send it home';}
function choose(i){if(state!=='playing'||paused||flight)return;if(boxes[i].address!==address){time=Math.max(0,time-3);streak=0;toast('Wrong address! −3 seconds');beep(150);return}selected=i;step=0;parcelMax=Math.max(2.5,4.5+boxes[i].size*1.5-level*.18)+up.sort*1.2;parcelTime=parcelMax;renderBoxes();beep(360)}
function input(k){if(state!=='playing'||paused||flight||selected<0)return;let b=boxes[selected];if(b.seq[step]===k){step++;beep(440+step*80);if(step===b.seq.length){send();return}}else{time=Math.max(0,time-2);step=0;streak=0;toast('Oops! −2 seconds');beep(150)}renderBoxes()}
function send(){let b=boxes[selected];let pts=(100+b.size*35+Math.min(streak,8)*10)*(delivered>=quota?2:1);pts=Math.round(pts*(1+up.tip*.2));score+=pts;coins+=delivered>=quota?3:2;streak++;delivered++;needed--;flight={t:0,pts};selected=-1;step=0;renderBoxes();toast('Delivered! +'+pts+(streak>2?' · '+streak+' streak':''));if(delivered===quota){beep(900);toast('Quota complete! Double-point bonus time');}update()}
function afterFlight(){flight=null;if(needed<=0){address+=2;needed=1+Math.floor(Math.random()*3);targetOffset+=340;}makeBoxes();update()}
function update(){ $('round').innerHTML=String(level).padStart(2,'0')+' <small>Maple Lane</small>';$('quota').innerHTML=delivered+' <small>/ '+quota+' parcels</small>';$('clock').innerHTML=Math.ceil(time)+'<span>s</span>';$('clock').style.color=time<10?'#bc613f':'';$('score').textContent=String(score).padStart(4,'0');$('progress').style.width=Math.min(100,delivered/quota*100)+'%';$('phase').textContent=delivered>=quota?'BONUS TIME · DOUBLE POINTS':'MAKE YOUR QUOTA';$('status').textContent=delivered>=quota?'Every extra parcel is a little extra payday.':Math.max(0,quota-delivered)+' more parcels to unlock bonus time.';$('address').textContent=address+' Maple Lane';$('remaining').textContent=needed+' parcel'+(needed===1?'':'s')+' requested';$('finish').hidden=!(state==='playing'&&delivered>=quota);}
function saveBest(){if(score>best){best=score;try{localStorage.setItem('parcelBest',best)}catch(e){}$('best').textContent='BEST '+best}}
function endRound(){if(state!=='playing')return;saveBest();flight=null;if(delivered>=quota){state='garage';garage()}else{state='over';modal('<span class="eyebrow">THE SHIFT IS OVER</span><h1>A good day<br>on the lane.</h1><p>You delivered '+delivered+' of '+quota+' parcels on route '+level+'. Final score: <b>'+score+'</b>. Your best: '+best+'.</p><p>Tip: choose the matching address first. Large boxes give you longer to finish their arrows.</p><button class="primary" id="restart">Start a fresh shift →</button>');$('restart').onclick=()=>{level=1;score=0;coins=0;up={clock:0,sort:0,tip:0};address=12;targetOffset=offset=0;hide();startRound()}}update()}
function garage(){modal('<span class="eyebrow">ROUTE '+level+' COMPLETE · THE LITTLE GARAGE</span><h1>Take a breather.<br>Tune your truck.</h1><p>'+delivered+' parcels delivered · '+score+' points<br><b>'+coins+' tips</b> to spend. Upgrades last for this shift.</p>'+[['clock','A longer lunch break','+8 seconds every round'],['sort','Organized cargo','+1.2 seconds per parcel sequence'],['tip','Neighborhood favorite','+20% delivery points']].map(([id,title,desc])=>'<button class="upgrade" data-up="'+id+'" '+(coins<6+up[id]*4?'disabled':'')+'><b>'+title+'</b> · '+(6+up[id]*4)+' tips <small>'+desc+' · Level '+up[id]+'</small></button>').join('')+'<button class="primary" id="next">Next route →</button>');document.querySelectorAll('[data-up]').forEach(b=>b.onclick=()=>{let id=b.dataset.up,cost=6+up[id]*4;if(coins>=cost){coins-=cost;up[id]++;beep(700);garage()}});$('next').onclick=()=>{level++;hide();startRound()}}
function togglePause(){if(state!=='playing')return;paused=!paused;$('pause').textContent=paused?'Resume':'Pause';if(paused){modal('<span class="eyebrow">PARKED FOR A MOMENT</span><h1>Enjoy the view.</h1><p>Your route is waiting right where you left it.</p><button class="primary" id="resume">Back to deliveries →</button>');$('resume').onclick=togglePause}else hide()}
$('pause').onclick=togglePause;$('finish').onclick=endRound;$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';beep()};document.addEventListener('keydown',e=>{if(keymap[e.key]){e.preventDefault();input(keymap[e.key])}else if(/^[1-4]$/.test(e.key))choose(+e.key-1);else if(e.key.toLowerCase()==='p'||e.key==='Escape')togglePause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing'&&!paused)togglePause()});
// A true parallel projection: every object uses the same scale, regardless of depth.
let W=1000,H=440,scale=1;
function point(x,y,z=0){return {x:W*.49+(x-y)*.82*scale,y:H*.55+(x+y)*.38*scale-z*scale}}
function poly(points,color){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=color;ctx.fill()}
function shade(hex,n){let a=hex.replace('#','');return '#'+[0,2,4].map(i=>Math.max(0,Math.min(255,parseInt(a.slice(i,i+2),16)+n)).toString(16).padStart(2,'0')).join('')}
function cube(x,y,z,w,d,h,c){let a=point(x,y,z+h),b=point(x+w,y,z+h),cc=point(x+w,y+d,z+h),dd=point(x,y+d,z+h);poly([dd,cc,point(x+w,y+d,z),point(x,y+d,z)],shade(c,-18));poly([b,cc,point(x+w,y+d,z),point(x+w,y,z)],shade(c,-32));poly([a,b,cc,dd],shade(c,16));}
function ground(x,y,w,d,c){poly([point(x,y),point(x+w,y),point(x+w,y+d),point(x,y+d)],c)}
function shadow(x,y,w,d){ground(x+12,y+10,w,d,'#38543720')}
function tree(x,y,s=1){shadow(x,y,40*s,40*s);cube(x+15*s,y+15*s,0,10*s,10*s,37*s,'#91734c');cube(x,y,30*s,43*s,43*s,34*s,'#739056');cube(x+5*s,y+5*s,64*s,32*s,32*s,23*s,'#8ca362');}
function person(x,y,t,i){let bob=Math.sin(t*5+i)*1.5;let shirt=['#cf8256','#d3af51','#668e91','#a97b79'][i%4];cube(x,y,0,7,11,4,'#303b38');cube(x+10,y,0,7,11,4,'#303b38');cube(x,y,4,17,10,16,'#527892');cube(x-2,y-1,20+bob,21,12,17,shirt);cube(x+2,y,37+bob,13,11,12,'#d5ab7b');cube(x+1,y-1,48+bob,15,13,4,'#6b5845');}
function house(x,y,n,i){let colors=['#d8b56a','#c87e64','#95aaa1','#ddd0ab','#83a1a8'];let c=colors[((i%5)+5)%5];shadow(x,y,126,106);ground(x-15,y-15,158,133,'#acc28b');ground(x+45,y+98,28,71,'#ded4ba');cube(x,y,0,118,96,74,c);cube(x-7,y-6,74,132,108,9,'#aa6550');cube(x+12,y+10,83,94,84,17,'#b66d54');cube(x+33,y+27,100,50,50,13,'#b66d54');cube(x+91,y+16,91,16,18,32,'#aa8d72');cube(x+46,y+96,0,24,3,43,'#547b73');cube(x+13,y+97,29,21,2,24,'#e4e4c0');cube(x+83,y+97,29,21,2,24,'#e4e4c0');cube(x+22,y+99,29,2,1,24,'#728f88');cube(x+92,y+99,29,2,1,24,'#728f88');cube(x+39,y+99,0,39,15,5,'#d7c7a9');let p=point(x+58,y+101,56);ctx.fillStyle='#fff6da';ctx.font=`600 ${11*scale}px sans-serif`;ctx.textAlign='center';ctx.fillText(n,p.x,p.y);cube(x+122,y+145,0,4,4,25,'#a18c6b');cube(x+116,y+141,24,17,11,9,'#b16450');for(let j=0;j<3;j++)cube(x-8+j*19,y+108,0,15,15,12,'#809b62');if(i%2===0)tree(x+140,y+25,.8);}
function truck(){let x=-50,y=100;shadow(x,y,135,68);for(let xx of [x+19,x+103]){cube(xx,y-4,4,21,13,24,'#343e3b');cube(xx,y+54,4,21,13,24,'#343e3b');cube(xx+5,y+66,10,10,2,11,'#a8aea0')}cube(x,y,17,91,60,66,'#d6a448');cube(x+91,y+2,17,43,56,47,'#d6a448');cube(x+99,y+1,42,29,1,20,'#8eafa9');cube(x+134,y+8,40,1,43,22,'#8eafa9');cube(x+88,y-3,64,49,65,7,'#e8bf69');cube(x+132,y+5,18,5,52,8,'#efe5c9');cube(x+137,y+7,29,2,9,7,'#fff2ba');cube(x+137,y+48,29,2,9,7,'#fff2ba');let p=point(x+43,y+61,52);ctx.fillStyle='#fff5dc';ctx.font=`bold ${13*scale}px sans-serif`;ctx.textAlign='center';ctx.fillText('PARCEL',p.x,p.y);ctx.font=`${8*scale}px sans-serif`;ctx.fillText('LANE POST',p.x,p.y+12*scale);cube(x+5,y+3,83,72,54,3,'#d5aa58');}
function draw(){let rect=canvas.getBoundingClientRect(),dpr=devicePixelRatio||1;if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr)}W=rect.width;H=rect.height;scale=Math.max(.6,Math.min(1.1,W/1100));ctx.setTransform(dpr,0,0,dpr,0,0);ctx.fillStyle='#bfd0a0';ctx.fillRect(0,0,W,H);ground(-1500,30,3000,75,'#d8d0b8');ground(-1500,105,3000,155,'#8d9690');ground(-1500,260,3000,18,'#d7d1b9');for(let i=-9;i<10;i++)ground(i*100-offset%100,180,43,4,'#d9d5b9');for(let i=-4;i<6;i++){let x=i*340-(offset%340)-80;house(x,-150,address+(i-Math.floor((targetOffset-offset)/340))*2,i+Math.floor(offset/340));if(i%2)tree(x+235,-110,.95);person(x+180+(worldTime*12+i*60)%90,65,worldTime,i+8)}truck();for(let i=-4;i<5;i++){let x=i*270-offset%270;tree(x,325,1.1);ground(x+65,290,57,45,'#a8bd86');if(i%2===0)person(x+120-(worldTime*8)%90,290,worldTime,i+10)}if(flight){let t=flight.t/.65,a=point(5,125,60),b=point(25,-50,18);let x=a.x+(b.x-a.x)*t,y=a.y+(b.y-a.y)*t-Math.sin(t*Math.PI)*95*scale;ctx.save();ctx.translate(x,y);ctx.rotate(t*5);ctx.fillStyle='#bd8c50';ctx.fillRect(-10,-10,20,20);ctx.fillStyle='#ead1a0';ctx.fillRect(-3,-10,6,20);ctx.restore()} }
function tick(now){let dt=Math.min((now-last)/1000,.05);last=now;if(!paused){worldTime+=dt;offset+=(targetOffset-offset)*Math.min(1,dt*4);if(state==='playing'){time=Math.max(0,time-dt);if(selected>=0){parcelTime-=dt;let bar=document.querySelector('.box.selected .bar i');if(bar)bar.style.width=Math.max(0,parcelTime/parcelMax*100)+'%';if(parcelTime<=0){time=Math.max(0,time-2);selected=-1;step=0;streak=0;toast('Parcel timer expired! Pick it again · −2s');renderBoxes()}}if(flight){flight.t+=dt;if(flight.t>=.65)afterFlight()}if(time<=0)endRound();update()}}if(now>toastUntil)$('toast').classList.remove('show');draw();requestAnimationFrame(tick)}
